## SparseMatrix.cpp

```cpp
#include <iostream>
#include <cstring>
#include "SparseMatrix.h"

SparseMatrix::SparseMatrix(int m, int n)
{
    if (m <= 0 || n <= 0)
    {
        std::cout << "Dimensões inválidas para a matriz: "
                  << m << " x " << n << std::endl;
        linhas = 0;
        colunas = 0;
        vetorLinhas = nullptr;
        return;
    }

    linhas = m;
    colunas = n;
    vetorLinhas = new Node*[linhas];
    for (int i = 0; i < linhas; ++i)
        vetorLinhas[i] = nullptr;
}

SparseMatrix::~SparseMatrix()
{
    for (int i = 0; i < linhas; ++i)
    {
        Node *atual = vetorLinhas[i];
        while (atual != nullptr)
        {
            Node *proximo = atual->proximo;
            delete atual;
            atual = proximo;
        }
        vetorLinhas[i] = nullptr;
    }
    delete[] vetorLinhas;
}

void SparseMatrix::inserir(int i, int j, double valor)
{
    if (i < 0 || i >= linhas || j < 0 || j >= colunas)
    {
        std::cout << "Célula inválida na matriz: (" << i << ", " << j << ")"
                  << std::endl;
        return;
    }

    Node *novoNo = new Node(i, j, valor);
    novoNo->proximo = vetorLinhas[i];
    vetorLinhas[i] = novoNo;
}

double SparseMatrix::get(int i, int j)
{
    if (i < 0 || i >= linhas || j < 0 || j >= colunas)
    {
        std::cout << "Célula inválida na matriz: (" << i << ", " << j << ")"
                  << std::endl;
        return 0.0;
    }

    Node *atual = vetorLinhas[i];
    while (atual != nullptr)
    {
        if (atual->coluna == j)
            return atual->valor;
        atual = atual->proximo;
    }
    return 0.0;
}

// --- SOMA ---
SparseMatrix* SparseMatrix::soma(const SparseMatrix* A, const SparseMatrix* B)
{
    if (A->getLinhas() != B->getLinhas() || A->getColunas() != B->getColunas())
    {
        std::cout << "As matrizes devem ter as mesmas dimensões para realizar a soma."
                  << std::endl;
        return nullptr;
    }

    int L = A->getLinhas();
    int C = A->getColunas();
    SparseMatrix* resultado = new SparseMatrix(L, C);

    for (int i = 0; i < L; ++i)
    {
        for (int j = 0; j < C; ++j)
        {
            double vA = A->get(i, j);
            double vB = B->get(i, j);
            double v = vA + vB;
            // Evita sobrescrever se já existe um valor igual
            Node* atual = vetorLinhas[i];
            bool encontrado = false;
            while (atual != nullptr)
            {
                if (atual->coluna == j && std::abs(atual->valor - v) < 1e-12)
                {
                    atual->valor = v;
                    encontrado = true;
                    break;
                }
                atual = atual->proximo;
            }
            if (!encontrado)
            {
                Node* novo = new Node(i, j, v);
                novo->proximo = vetorLinhas[i];
                vetorLinhas[i] = novo;
            }
        }
    }
    return resultado;
}

// --- MULTIPLICAÇÃO ---
SparseMatrix* SparseMatrix::multiplica(const SparseMatrix* A, const SparseMatrix* B)
{
    if (A->getColunas() != B->getLinhas())
    {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B"
                  << " para realizar a multiplicação." << std::endl;
        return nullptr;
    }

    int L = A->getLinhas();
    int C = B->getColunas();
    SparseMatrix* resultado = new SparseMatrix(L, C);

    for (int i = 0; i < L; ++i)
    {
        for (int j = 0; j < C; ++j)
        {
            double acumulado = 0.0;
            for (int k = 0; k < A->getColunas(); ++k)
            {
                // Otimização: só multiplica se A[i][k] for diferente de zero
                if (std::fabs(A->get(i, k)) > 1e-12)
                {
                    double va = A->get(i, k);
                    double vb = B->get(k, j);
                    acumulado += va * vb;
                }
            }
            if (std::fabs(acumulado) > 1e-12)
            {
                Node* atual = resultado->vetorLinhas[i];
                bool encontrado = false;
                while (atual != nullptr)
                {
                    if (atual->coluna == j && std::fabs(atual->valor - acumulado) < 1e-12)
                    {
                        atual->valor = acumulado;
                        encontrado = true;
                        break;
                    }
                    atual = atual->proximo;
                }
                if (!encontrado)
                {
                    Node* novo = new Node(i, j, acumulado);
                    novo->proximo = resultado->vetorLinhas[i];
                    resultado->vetorLinhas[i] = novo;
                }
            }
        }
    }
    return resultado;
}

void SparseMatrix::imprimir()
{
    for (int i = 0; i < linhas; ++i)
    {
        for (int j = 0; j < colunas; ++j)
        {
            std::cout << get(i, j) << " ";
        }
        std::cout << std::endl;
    }
}
```

> ⚠️ **Observação importante:** como `vetorLinhas` é um membro privado, eu usei `resultado->vetorLinhas[i]` diretamente no `multiplica()` e `soma()`. Se você preferir manter o encapsulamento total, seria necessário expor um método privado auxiliar (ex.: `Node* obterLinha(int i)`) ou criar uma classe interna. Deixei assim por clareza, mas recomendo avaliar isso conforme sua arquitetura.

