    std::cout << "\n----- Matriz A -----" << std::endl;
    A->imprimir();

    std::cout << "\n----- Matriz B -----" << std::endl;
    B->imprimir();

    // Soma
    std::cout << "\n----- Soma (A + B) -----" << std::endl;
