    if (somaResult != nullptr)
    {
        somaResult->imprimir();
        delete somaResult;
    }

    // Multiplicação
    std::cout << "\n----- Multiplicação (A × B) -----" << std::endl;
    SparseMatrix* multResult = multiplica(A, B);
    if (multResult != nullptr)
    {
        multResult->imprimir();
        delete multResult;
    }

    // Limpeza
    delete A;
    delete B;

    return 0;
}
