module.exports = class RegisterAppCommand extends Command {
    constructor(client) {
        super(client, {
            name: "registerapp",
            description: "Registra uma aplicação.",
            slash: true,
            default_member_permissions: PermissionsBitField.Flags.Administrator,
            options: [
                {
                    name: "usuario",
                    type: ApplicationCommandOptionType.User,
                    description: "Usuário alvo.",
                    required: true,
                },
                {
                    name: "valor_mensal",
                    type: ApplicationCommandOptionType.Integer,
                    description: "Valor mensal da aplicação.",
                    required: true,
                    min_value: 0, // Adiciona validação para valores não negativos
                },
                {
                    name: "tipo_aplicativo",
                    description: "Tipo do aplicativo",
                    type: ApplicationCommandOptionType.String,
                    required: true,
                    choices: [
                        { name: "Bateponto 1", value: "bateponto1" },
                        { name: "Bateponto 2", value: "bateponto2" },
                        { name: "Ticket", value: "ticket" },
                        { name: "MMORPG", value: "mmorpg" },
                        { name: "Outros", value: "others" },
                    ],
                },
                {
                    name: "id_aplicacao",
                    type: ApplicationCommandOptionType.String,
                    description: "ID da aplicação.",
                    required: false,
                },
                {
                    name: "id_servidor",
                    type: ApplicationCommandOptionType.String,
                    description: "ID do servidor.",
                    required: false,
                },
            ],
        });
    }

    async run(interaction) {
        const { user, options } = interaction;

        // Verificar se o usuário tem permissão
        if (user.id !== config.AUTHORIZED_USER_ID) {
            return interaction.reply({
                content: "Você não tem permissão para usar esse comando.",
                ephemeral: true,
            });
        }

        await interaction.deferReply({ ephemeral: true });

        // Extrair opções do comando
        const appId = options.getString("id_aplicacao");
        const appType = options.getString("tipo_aplicativo");
        const targetUser = options.getUser("usuario");
        const monthlyFee = options.getInteger("valor_mensal");
        const serverId = options.getString("id_servidor");

        // Validação do usuário alvo
        const member = await interaction.guild.members.fetch(targetUser.id).catch(() => null);
        if (!member) {
            return interaction.editReply({
                content: `<:n_negative:1261856702496636958> Não foi possível encontrar o usuário especificado.`,
                ephemeral: true,
            });
        }

        try {
            // Verificar se a aplicação já está registrada
            const existingApp = await Application.findOne({ applicationId: appId });
            if (existingApp) {
                return interaction.editReply({
                    content: `<:n_negative:1261856702496636958> Esta aplicação já está registrada no banco de dados \`(${existingApp.applicationId})\` ${existingApp.owner ? `- Dono: <@${existingApp.owner}>` : "(sem usuário definido)"}`,
                    ephemeral: true,
                });
            }

            // Determinar o hostId
            const hostId = appId || config.APPS_IDS[appType];
            if (!hostId) {
                return interaction.editReply({
                    content: `<:n_negative:1261856702496636958> Tipo de aplicativo inválido ou não suportado.`,
                    ephemeral: true,
                });
            }

            // Buscar informações da aplicação pela API (certifique-se de que a API está corretamente configurada)
            const api = this.client.square_api;
            const appData = await api.applications.get(hostId).catch(() => null);

            if (!appData) {
                return interaction.editReply({
                    content: `<:n_negative:1261856702496636958> Não foi possível encontrar a aplicação com o ID fornecido.`,
                    ephemeral: true,
                });
            }

            const now = new Date();

            // Criar novo registro de aplicação
            const newApplication = new Application({
                applicationId: appId || `shared-${crypto.randomBytes(10).toString("hex")}`,
                name: appData.name || "Aplicação sem nome",
                hostId: hostId,
                owner: targetUser.id,
                clientId: appData.clientId,
                sharedClient: !appId,
                product: appType,
                createdAt: now,
                monthlyFee: monthlyFee,
                lastRenovationAt: now,
